Let's locate after vertical bounce condition at lines 44-49. We'll add playBounce there.

Also need to define playBounce function earlier.

Implement:

function playBounce() {
  const ctxAudio = new (window.AudioContext || window.webkitAudioContext)();
  const oscillator = ctxAudio.createOscillator();
  const gain = ctxAudio.createGain();
  oscillator.type = 'sine';
  oscillator.frequency.setValueAtTime(200, ctxAudio.currentTime);
  oscillator.connect(gain);
  gain.connect(ctxAudio.destination);
  oscillator.start();
  gain.gain.exponentialRampToValueAtTime(0.00001, ctxAudio.currentTime + 0.1);
  oscillator.stop(ctxAudio.currentTime + 0.1);
}

